INSERT INTO "Criterion" ("id", "title", "description", "maxScore", "criterionOrder", "createdAt") VALUES (1, 'คลิปสร้างสรรค์สื่อถึงและแสดงออกถึงความเป็นไทย', 'การนำเสนอเนื้อหาความคิดสร้างสรรค์ บ่งบอกถึงอัตลักษณ์ความเป็นไทยอย่างชัดเจน', 40, 1, 1788361252295);
INSERT INTO "Criterion" ("id", "title", "description", "maxScore", "criterionOrder", "createdAt") VALUES (2, 'ท่าทางถูกต้องตามโจทย์ที่กำหนดและสวยงาม มีความเป็นธรรมชาติ คล่องแคล่ว นุ่มนวล มีทักษะ มีความพร้อมเพรียง', 'ความถูกต้องตามท่าทาง ความพร้อมเพรียง ความสวยงามและความเป็นธรรมชาติ', 30, 2, 1788361252297);
INSERT INTO "Criterion" ("id", "title", "description", "maxScore", "criterionOrder", "createdAt") VALUES (3, 'ความตรงต่อเวลา / นักเรียนครบตามจำนวน', 'ส่งผลงานตรงตามเวลาที่กำหนด และมีจำนวนสมาชิกนักเรียนครบถ้วนตามเกณฑ์', 10, 3, 1788361252299);
INSERT INTO "Criterion" ("id", "title", "description", "maxScore", "criterionOrder", "createdAt") VALUES (4, 'การถ่ายทำ ตัดต่อ บันทึกภาพ ชัดเจน', 'คุณภาพของภาพและเสียง ความลื่นไหลของการตัดต่อและการจัดองค์ประกอบภาพ', 10, 4, 1788361252302);
INSERT INTO "Criterion" ("id", "title", "description", "maxScore", "criterionOrder", "createdAt") VALUES (5, 'ไม่มีคำหยาบ ความรุนแรง บุคลิกภาพ การแต่งกายเป็นระเบียบเรียบร้อย', 'ความสุภาพเรียบร้อย ความเหมาะสมของเนื้อหา และการแต่งกายถูกต้องตามระเบียบ', 10, 5, 1788361252304);
